"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[403],{20403:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/metamorphosis.png\\"\\n          title=\\"변신\\"\\n          author=\\"프란츠 카프카\\"\\n          publisher=\\"더클래식\\"\\n          publishedDate=\\"2018-11-20\\"\\n          isbn=\\"9791189581992\\"\\n          rating=5\\n          tags=\\"novel\\"\\n        />\\n</center>\\n\\n## Review\\n집안의 가장으로서 가족을 부양하며 성실하게 살아왔지만, 괴물로 변하자마자 가족들은 점점 그를 거부하고 혐오하게 된다.  \\n시간이 흐르면서 그는 방 안에 갇힌 채 점점 쇠약해지고, 아무도 슬퍼하지 않는 죽음을 맞이한다.  \\n가족은 그가 죽자마자 안도하며 새로운 시작을 준비한다.  \\n<br>\\n한 인간이 사회적 기능을 잃었을 때 겪는 <mark>존재 삭제</mark>를 그린다.  \\n발표된 지 1세기가 넘었지만, 이 작품이 담고 있는 주제는 여전히 현대 사회에도 깊이 공감된다.  \\n<br>\\n```당신이 벌레가 되었을 때, 세상은 얼마나 빨리 당신을 버릴까```"}')}}]);